func (CreateMessageType) Values() []string {
	return []string{
		string(CreateMessageTypeText),
		string(CreateMessageTypeTemplate),
		string(CreateMessageTypeReaction),
		string(CreateMessageTypeEdit),
		string(CreateMessageTypeRevoke),
	}
}

// Validate reports whether e is a defined CreateMessageType value.
func (e CreateMessageType) Validate() error {
	switch e {
	case CreateMessageTypeText, CreateMessageTypeTemplate, CreateMessageTypeReaction, CreateMessageTypeEdit, CreateMessageTypeRevoke:
		return nil
	default:
		return errors.New("invalid CreateMessageType: " + string(e))
	}
}

// String returns e as a plain string.
func (e CreateMessageType) String() string {
	return string(e)
}

type SendMessageTemplate struct {
	ID     string                     `json:"id"`     // The message template to render.
	Params map[string]json.RawMessage `json:"params"` // A value for every template parameter, by parameter name.
}

// MessageReaction sets the agent's reaction on a chat message.
type MessageReaction struct {
	// ID of the chat message to react to. A message sent through the API
	// can be identified by its message ID. Reacting to a received message
	// requires `whatsapp.inbound.read`.
	TargetID string `json:"target_id"`
	Emoji    string `json:"emoji,omitzero"` // One emoji; an empty string removes the agent's reaction.
}

// MessageEdit replaces the text of one of the agent's own text messages,
// within 20 minutes of its send.
type MessageEdit struct {
	TargetID string `json:"target_id"` // The chat message to edit.
	Body     string `json:"body"`      // The new message text.
}

// MessageRevoke deletes one of the agent's own messages for everyone,
// within 48 hours of its send.
type MessageRevoke struct {
	TargetID string `json:"target_id"` // The chat message to delete for everyone.
}

// How the recipient is resolved before sending a message.
type SendMessageStrategy string

const (
	SendMessageStrategyOnlyPhone   SendMessageStrategy = "only_phone"
	SendMessageStrategyPreferPhone SendMessageStrategy = "prefer_phone"
	SendMessageStrategyOnlyLid     SendMessageStrategy = "only_lid"
	SendMessageStrategyPreferLid   SendMessageStrategy = "prefer_lid"
)

// Values returns the valid SendMessageStrategy values.
func (SendMessageStrategy) Values() []string {
	return []string{
		string(SendMessageStrategyOnlyPhone),
		string(SendMessageStrategyPreferPhone),
		string(SendMessageStrategyOnlyLid),
		string(SendMessageStrategyPreferLid),
	}
}

// Validate reports whether e is a defined SendMessageStrategy value.
func (e SendMessageStrategy) Validate() error {
	switch e {
	case SendMessageStrategyOnlyPhone, SendMessageStrategyPreferPhone, SendMessageStrategyOnlyLid, SendMessageStrategyPreferLid:
		return nil
	default:
		return errors.New("invalid SendMessageStrategy: " + string(e))
	}
}

// String returns e as a plain string.
func (e SendMessageStrategy) String() string {
	return string(e)
}

type CreateMessageOutput struct {
	Message *Message `json:"message,omitzero"` // The accepted message.
}

type FetchMessageInput struct {
	MessageID string `json:"-"` // The message to read.
}

type FetchMessageOutput struct {
	Message *Message `json:"message,omitzero"` // The message with its receipt state.
}
